mapper.update:
UPDATE activity
SET proposal = #{proposal},
    version = version + 1
WHERE id = #{id}
  AND org_id = #{orgId}
  AND status = 'DRAFT'
  AND version = #{version}

UPDATE activity
SET status = #{toStatus},
    version = version + 1
WHERE id = #{id}
  AND org_id = #{orgId}
  AND status = #{fromStatus}

UPDATE activity
SET confirmed_at = CURRENT_TIMESTAMP(6)
WHERE id = #{id}
  AND org_id = #{orgId}

UPDATE activity
SET review_note = #{reviewNote},
    submitted_by = #{submittedBy},
    confirmed_by = #{confirmedBy},
    confirm_type = #{confirmType}
WHERE id = #{id}
  AND org_id = #{orgId}

mapper.delete:
DELETE FROM activity
WHERE id = #{id}
  AND org_id = #{orgId}
  AND status = 'DRAFT'

mapper.update:
UPDATE activity
name = #{name}, description = #{description}, owner_member_id = #{ownerMemberId}, start_time = #{startTime}, end_time = #{endTime}, location = #{location}, budget = #{budget}, registration_scope = #{registrationScope}, capacity = #{capacity}, registration_start = #{registrationStart}, registration_end = #{registrationEnd}, version = version + 1,
WHERE id = #{id} AND org_id = #{orgId}
AND status = #{status}
AND version = #{version}

UPDATE activity
SET status = 'EXECUTING',
    started_at = CURRENT_TIMESTAMP(6),
    execution_snapshot_hash = #{snapshotHash},
    version = version + 1
WHERE id = #{id}
  AND org_id = #{orgId}
  AND status = 'APPROVED'
  AND version = #{version}

UPDATE activity
SET status = 'REVIEWING',
    ended_at = CURRENT_TIMESTAMP(6),
    version = version + 1
WHERE id = #{id}
  AND org_id = #{orgId}
  AND status = 'EXECUTING'
  AND version = #{version}

UPDATE activity
SET status = 'ARCHIVED',
    archived_at = CURRENT_TIMESTAMP(6),
    version = version + 1
WHERE id = #{id}
  AND org_id = #{orgId}
  AND status = #{fromStatus}
  AND version = #{version}

UPDATE activity
SET status = 'CANCELLED',
    cancelled_at = CURRENT_TIMESTAMP(6),
    cancel_reason = #{reason},
    registration_open = FALSE,
    version = version + 1
WHERE id = #{id}
  AND org_id = #{orgId}
  AND status IN ('APPROVED', 'EXECUTING', 'REVIEWING')
  AND version = #{version}

UPDATE activity
SET status = #{toStatus},
    reopen_reason = #{reason},
    reopen_count = reopen_count + 1,
    version = version + 1
WHERE id = #{id}
  AND org_id = #{orgId}
  AND status = #{fromStatus}
  AND version = #{version}

UPDATE activity
SET summary = #{summary},
    summary_confirmed_at = NULL,
    summary_confirmed_by = NULL,
    summary_source_hash = NULL,
    version = version + 1
WHERE id = #{id}
  AND org_id = #{orgId}
  AND version = #{version}
  AND status IN ('REVIEWING', 'CANCELLED')

UPDATE activity
SET summary_confirmed_at = CURRENT_TIMESTAMP(6),
    summary_confirmed_by = #{accountId},
    summary_source_hash = #{sourceHash},
    version = version + 1
WHERE id = #{id}
  AND org_id = #{orgId}
  AND version = #{version}
  AND status IN ('REVIEWING', 'CANCELLED')
